import torch,torch.nn as nn; exec("class Solution(nn.Module):\n    def __init__(self, vocabulary_size):\n        super().__init__()\n        torch.manual_seed(0)\n        self.embedding = nn.Embedding(vocabulary_size, 16)\n        self.linear = nn.Linear(16, 1)\n        self.sigmoid = nn.Sigmoid()\n    def forward(self, x):\n        x = self.embedding(x)\n        x = x.mean(dim=1)\n        x = self.linear(x)\n        x = self.sigmoid(x)\n        return x")